use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [doc = " Result of a (potentially partial) decode operation without replacement."] # [must_use] # [derive (Debug , PartialEq , Eq)] pub enum DecoderResult { # [doc = " The input was exhausted."] # [doc = ""] # [doc = " If this result was returned from a call where `last` was `true`, the"] # [doc = " decoding process has completed. Otherwise, the caller should call a"] # [doc = " decode method again with more input."] InputEmpty , # [doc = " The decoder cannot produce another unit of output, because the output"] # [doc = " buffer does not have enough space left."] # [doc = ""] # [doc = " The caller must provide more output space upon the next call and re-push"] # [doc = " the remaining input to the decoder."] OutputFull , # [doc = " The decoder encountered a malformed byte sequence."] # [doc = ""] # [doc = " The caller must either treat this as a fatal error or must append one"] # [doc = " REPLACEMENT CHARACTER (U+FFFD) to the output and then re-push the"] # [doc = " the remaining input to the decoder."] # [doc = ""] # [doc = " The first wrapped integer indicates the length of the malformed byte"] # [doc = " sequence. The second wrapped integer indicates the number of bytes"] # [doc = " that were consumed after the malformed sequence. If the second"] # [doc = " integer is zero, the last byte that was consumed is the last byte of"] # [doc = " the malformed sequence. Note that the malformed bytes may have been part"] # [doc = " of an earlier input buffer."] # [doc = ""] # [doc = " The first wrapped integer can have values 1, 2, 3 or 4. The second"] # [doc = " wrapped integer can have values 0, 1, 2 or 3. The worst-case sum"] # [doc = " of the two is 6, which happens with ISO-2022-JP."] Malformed (u8 , u8) , }
}